import React from 'react';
import './NewsNotices.css';

const ContentListView = ({ title, type }) => {
    // Example data - in a real app, these would come from your SQL database
    const items = [
        { id: 1, title: `Annual General Meeting 2026 ${type}`, date: "2026-04-01", fileUrl: "/assets/sample.pdf", fileType: "pdf" },
        { id: 2, title: `Quarterly Financial Report Q3`, date: "2026-03-15", fileUrl: "/assets/rates.jpg", fileType: "image" },
    ];

    return (
        <div className="content-view-container">
            <div className="content-header">
                <h2>{title}</h2>
                <div className="upload-section">
                    <label className="upload-label">
                        Upload New {type}: 
                        <input type="file" onChange={(e) => alert('File selected: ' + e.target.files[0].name)} />
                    </label>
                </div>
            </div>

            <div className="item-list">
                {items.map(item => (
                    <div key={item.id} className="content-item">
                        <div className="item-info">
                            <span className="item-date">{item.date}</span>
                            <h3>{item.title}</h3>
                        </div>
                        <div className="item-actions">
                            <a href={item.fileUrl} target="_blank" rel="noreferrer" className="action-btn view">View</a>
                            <a href={item.fileUrl} download className="action-btn download">Download</a>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default ContentListView;
